operation.add:
// SvetLamp watermark: the column is added on first use
$sl_column = $this->db->query("SHOW COLUMNS FROM `" . DB_PREFIX . "product` LIKE 'sl_watermark'");

if (!$sl_column->num_rows) {
	$this->db->query("ALTER TABLE `" . DB_PREFIX . "product` ADD `sl_watermark` TINYINT(1) NOT NULL DEFAULT '0'");
}

if (isset($this->request->post['sl_watermark_sent'])) {
	$data['sl_watermark'] = !empty($this->request->post['sl_watermark']);
} elseif (!empty($product_info) && isset($product_info['sl_watermark'])) {
	$data['sl_watermark'] = (bool)$product_info['sl_watermark'];
} else {
	$data['sl_watermark'] = false;
}

if (isset($data['sl_watermark_sent'])) {
	$this->db->query("UPDATE " . DB_PREFIX . "product SET sl_watermark = '" . (empty($data['sl_watermark']) ? 0 : 1) . "' WHERE product_id = '" . (int)$product_id . "'");
}

// Only the product form sends sl_watermark_sent, so other modules saving a product leave the mark as it is
if (isset($data['sl_watermark_sent'])) {
	$this->db->query("UPDATE " . DB_PREFIX . "product SET sl_watermark = '" . (empty($data['sl_watermark']) ? 0 : 1) . "' WHERE product_id = '" . (int)$product_id . "'");
}

// SvetLamp watermark: photo file names of products with the checkbox on, loaded once per page
private static $sl_product_images = null;

private function slIsProductImage($filename) {
	if (self::$sl_product_images === null) {
		self::$sl_product_images = array();

		$column = $this->db->query("SHOW COLUMNS FROM `" . DB_PREFIX . "product` LIKE 'sl_watermark'");

		if ($column->num_rows) {
			$query = $this->db->query("SELECT p.image FROM `" . DB_PREFIX . "product` p WHERE p.sl_watermark = '1' AND p.image <> '' UNION SELECT pi.image FROM `" . DB_PREFIX . "product_image` pi LEFT JOIN `" . DB_PREFIX . "product` p ON (p.product_id = pi.product_id) WHERE p.sl_watermark = '1' AND pi.image <> ''");

			foreach ($query->rows as $row) {
				self::$sl_product_images[$row['image']] = true;
			}
		}
	}

	return isset(self::$sl_product_images[$filename]) && is_file(DIR_IMAGE . 'svetlamp-watermark.png');
}

// Lays the diagonal «СветЛамп51» over the picture, scaled to its shorter side
private function slWatermark($image) {
	$width = $image->getWidth();
	$height = $image->getHeight();
	$side = min($width, $height);

	// Tiny previews (cart, compare) stay clean: the text would be unreadable there
	if ($side < 120 || !function_exists('imagecreatefrompng')) {
		return;
	}

	$canvas = $image->getImage();
	$mark = imagecreatefrompng(DIR_IMAGE . 'svetlamp-watermark.png');

	if (!$canvas || !$mark) {
		return;
	}

	imagealphablending($canvas, true);
	imagecopyresampled($canvas, $mark, (int)(($width - $side) / 2), (int)(($height - $side) / 2), 0, 0, $side, $side, imagesx($mark), imagesy($mark));
	imagedestroy($mark);
}

// Copies with the mark get their own names, so ticking or unticking the box takes effect at once
$sl_watermark = $this->slIsProductImage($filename);

if ($sl_watermark) {
	$image_new = 'cache/' . utf8_substr($filename, 0, utf8_strrpos($filename, '.')) . '-' . (int)$width . 'x' . (int)$height . '-sl.' . $extension;
}

if ($sl_watermark) {
					$image = new Image(DIR_IMAGE . $image_old);
					$this->slWatermark($image);
					$image->save(DIR_IMAGE . $image_new);
				} else {
					copy(DIR_IMAGE . $image_old, DIR_IMAGE . $image_new);
				}
